def choose_move(observation):
    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def clamp_step(a, b):
        return 0 if a == b else (1 if b > a else -1)

    def manhattan(p, q):
        return abs(p[0] - q[0]) + abs(p[1] - q[1])

    def safe_list(v):
        return v if isinstance(v, list) else (v if isinstance(v, tuple) else [])

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position", (0, 0)))
    ox, oy = pos(observation.get("opponent_position", (sx, sy)))
    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)
    role = observation.get("self_role", "pursuer")

    def greedy_to(target):
        tx, ty = pos(target, (sx, sy))
        return [clamp_step(sx, tx), clamp_step(sy, ty)]

    if env == "pursuit_evasion":
        if role == "pursuer":
            return greedy_to((ox, oy))
        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        target = max(corners, key=lambda c: (manhattan(c, (ox, oy)), manhattan(c, (sx, sy))))
        dx, dy = greedy_to(target)
        if abs((sx + dx) - ox) + abs((sy + dy) - oy) <= 1:
            if abs(sx - ox) >= abs(sy - oy):
                dx = clamp_step(ox, sx)
            else:
                dy = clamp_step(oy, sy)
        return [dx, dy]

    if env == "territory_control":
        targets = safe_list(observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or [])
        if targets:
            best = min(targets, key=lambda t: (manhattan(pos(t), (sx, sy)), manhattan(pos(t), (ox, oy))))
            return greedy_to(best)
        return [clamp_step(ox, sx), clamp_step(oy, sy)]

    resources = safe_list(observation.get("resources") or observation.get("resource_positions") or [])
    if resources:
        best = min(resources, key=lambda r: (manhattan(pos(r), (sx, sy)), manhattan(pos(r), (ox, oy))))
        dx, dy = greedy_to(best)
        if abs((sx + dx) - ox) + abs((sy + dy) - oy) <= 1 and manhattan((sx, sy), (ox, oy)) <= 2:
            if abs(sx - ox) >= abs(sy - oy):
                dx = clamp_step(ox, sx)
            else:
                dy = clamp_step(oy, sy)
        return [dx, dy]

    # Fallback: slight pressure toward opponent, but avoid obvious collision if adjacent.
    if abs(sx - ox) + abs(sy - oy) <= 1:
        if abs(sx - ox) >= abs(sy - oy):
            return [clamp_step(ox, sx), 0]
        return [0, clamp_step(oy, sy)]
    return [clamp_step(sx, ox), clamp_step(sy, oy)]

